import { ref } from 'vue'
import api from '@/services/api'
import { useAuthStore } from '@/stores/auth'
import type { PlatformAnalytics, PlatformData } from '@/types/analytics'
import type { AxiosError } from 'axios'

export type { PlatformAnalytics, PlatformData } from '@/types/analytics'

function isAxiosError(error: unknown): error is AxiosError {
  return typeof error === 'object' && error !== null && 'isAxiosError' in error
}

export function usePlatformAnalytics(platform: string) {
  const authStore = useAuthStore()
  const loading = ref(true)
  const error = ref<string | null>(null)
  const accountData = ref<PlatformData | null>(null)

  const fetchAnalytics = async () => {
    try {
      loading.value = true
      error.value = null
      const { data } = await api.get(`/api/analytics/${platform}`)
      accountData.value = data
    } catch (err: unknown) {
      if (isAxiosError(err)) {
        error.value = err.response?.data?.error || 'Failed to fetch analytics'
      } else {
        error.value = 'Failed to fetch analytics'
      }
      console.error('Analytics fetch error:', err)
    } finally {
      loading.value = false
    }
  }

  const fetchOverview = async () => {
    try {
      const { data } = await api.get('/api/analytics/overview')
      return data
    } catch (err: unknown) {
      console.error('Overview fetch error:', err)
      throw err
    }
  }

  return {
    loading,
    error,
    accountData,
    fetchAnalytics,
    fetchOverview
  }
}

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import api from '@/services/api'

interface User {
    id: string
    email: string
    name: string
    avatar?: string
}

export const useAuthStore = defineStore('auth', () => {
    const user = ref<User | null>((() => {
        try {
            const stored = localStorage.getItem('user')
            if (!stored || stored === 'null') return null
            return JSON.parse(stored) as User
        } catch {
            localStorage.removeItem('user')
            return null
        }
    })())
    const token = ref<string | null>(localStorage.getItem('token'))
    const isAuthenticated = computed(() => !!token.value)
    const isLoading = ref(false)

    const setAuth = (newUser: User, newToken: string) => {
        user.value = newUser
        token.value = newToken
        localStorage.setItem('user', JSON.stringify(newUser))
        localStorage.setItem('token', newToken)
    }

    const login = async (email: string, password: string) => {
        isLoading.value = true
        try {
            const { data } = await api.post('/auth/login', { email, password })
            setAuth(data.user, data.token)
            return { success: true }
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Login failed'
            return { success: false, error: message }
        } finally {
            isLoading.value = false
        }
    }

    const register = async (email: string, password: string, name: string) => {
        isLoading.value = true
        try {
            const { data } = await api.post('/auth/register', { email, password, name })
            setAuth(data.user, data.token)
            return { success: true }
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Registration failed'
            return { success: false, error: message }
        } finally {
            isLoading.value = false
        }
    }

    const logout = () => {
        user.value = null
        token.value = null
        localStorage.removeItem('user')
        localStorage.removeItem('token')
        window.location.href = '/login'
    }

    const checkSession = async () => {
        if (!token.value) return false

        try {
            const { data } = await api.get('/auth/me')
            user.value = data
            localStorage.setItem('user', JSON.stringify(data))
            return true
        } catch (error) {
            logout()
            return false
        }
    }

    return {
        user,
        token,
        isAuthenticated,
        isLoading,
        login,
        register,
        logout,
        checkSession,
        setAuth
    }
})

/// <reference types="vite/client" />

declare module '*.vue' {
    import type { DefineComponent } from 'vue'
    const component: DefineComponent<{}, {}, any>
    export default component
}
